import { createInitialState, normalizeState, calculateFinance, nextRecurrenceDate, createExportPayload, parseImportPayload } from "./ruan-core.js";

(() => {
  "use strict";
  const KEY = "ruan.personal.foundation.v1";
  const $ = (id) => document.getElementById(id);
  const nowISO = () => new Date().toISOString();
  const dateKey = () => new Date().toLocaleDateString("sv-SE");
  const money = (value) => new Intl.NumberFormat("pt-BR", {style:"currency",currency:"BRL"}).format(Number(value) || 0);
  const uid = () => globalThis.crypto?.randomUUID?.() || String(Date.now()) + Math.random().toString(16).slice(2);
  const initial = () => createInitialState();
  let state = load();
  function load(){try{const parsed=JSON.parse(localStorage.getItem(KEY)||"null");return parsed&&typeof parsed==="object"?normalizeState(parsed):initial()}catch{return initial()}}
  function save(){try{state.updatedAt=nowISO();localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify("Não foi possível salvar neste navegador. Exporte ou libere espaço antes de continuar.");return false}}
  function notify(message){const n=$("notice");n.textContent=message;n.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.hidden=true,4200)}
  function safe(text){return String(text??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
  function switchView(view){const target=$( "view-"+view );if(!target)return;document.querySelectorAll(".view").forEach(el=>el.classList.toggle("active",el===target));document.querySelectorAll("[data-view].nav-item").forEach(el=>el.classList.toggle("active",el.dataset.view===view));if(view==="tasks")renderTasks();if(view==="shopping")renderShopping();if(view==="reminders")renderReminders();if(view==="finance")renderFinance();if(view==="overview")renderOverview();window.scrollTo({top:0,behavior:"smooth"})}
  function addTask(title,category="Pessoal",priority="normal",recurrence=""){const today=dateKey();state.tasks.unshift({id:uid(),title:title.trim(),category,priority,recurrence:recurrence||null,dueDate:today,done:false,date:today,createdAt:nowISO()});save();renderAll()}
  function addReminder(title,when=""){state.reminders.unshift({id:uid(),title:title.trim(),when,done:false,createdAt:nowISO()});save();renderAll()}
  function addShoppingList(title){state.shoppingLists.unshift({id:uid(),title:title.trim(),items:[],createdAt:nowISO()});save();renderAll()}
  function empty(message){return '<div class="empty-state">'+safe(message)+'</div>'}
  function renderTasks(){const list=$("taskList");const today=state.tasks.filter(t=>t.date===dateKey());$("taskProgress").textContent=today.filter(t=>t.done).length+" de "+today.length+" concluídas hoje";list.innerHTML=state.tasks.length?state.tasks.map(t=>'<div class="task-row '+(t.done?"done":"")+'"><input class="check" type="checkbox" data-task-toggle="'+t.id+'" '+(t.done?"checked":"")+' aria-label="Concluir '+safe(t.title)+'"><div class="task-main"><strong>'+safe(t.title)+'</strong><small>'+safe(t.category)+' · '+(t.date===dateKey()?"Hoje":safe(t.date))+'</small></div><span class="tag '+safe(t.priority)+'">'+({high:"Importante",low:"Se der tempo",normal:"Normal"}[t.priority]||"Normal")+'</span><button class="delete-button" data-task-delete="'+t.id+'" aria-label="Excluir tarefa">×</button></div>').join(""):empty("Sua lista está vazia. Comece com uma tarefa pequena, como arrumar a cama.") }
  function renderShopping(){const el=$("shoppingLists");el.innerHTML=state.shoppingLists.length?state.shoppingLists.map(l=>'<article class="shopping-card"><div class="shopping-card-header"><div><h3>'+safe(l.title)+'</h3><p>'+l.items.filter(i=>i.done).length+' de '+l.items.length+' itens marcados</p></div><button class="delete-button" data-list-delete="'+l.id+'" aria-label="Excluir lista">×</button></div><form class="shopping-add" data-item-form="'+l.id+'"><input name="item" maxlength="100" placeholder="Adicionar item..." required><button type="submit" aria-label="Adicionar item">＋</button></form>'+(l.items.length?l.items.map(i=>'<label class="shopping-item '+(i.done?"checked":"")+'"><input class="check" type="checkbox" data-item-toggle="'+l.id+'" data-item-id="'+i.id+'" '+(i.done?"checked":"")+'> <span>'+safe(i.title)+'</span><button class="delete-button" type="button" data-item-delete="'+l.id+'" data-item-id="'+i.id+'" aria-label="Excluir item">×</button></label>').join(""):empty("Adicione os itens que precisa comprar."))+'</article>').join(""):empty("Nenhuma lista criada. Comece por “Mercado da semana”.")}
  function renderReminders(){const el=$("reminderList");const active=state.reminders.filter(r=>!r.done);active.sort((a,b)=>(a.when||"9999").localeCompare(b.when||"9999"));const completed=state.reminders.filter(r=>r.done);el.innerHTML=state.reminders.length?[...active,...completed].map(r=>'<div class="task-row '+(r.done?"done":"")+'"><input class="check" type="checkbox" data-reminder-toggle="'+r.id+'" '+(r.done?"checked":"")+' aria-label="Marcar lembrete"><div class="task-main"><strong>'+safe(r.title)+'</strong><small>'+(r.when?safe(new Date(r.when).toLocaleString("pt-BR")):"Sem data definida")+'</small></div><button class="delete-button" data-reminder-delete="'+r.id+'" aria-label="Excluir lembrete">×</button></div>').join(""):empty("Nenhum lembrete por enquanto. Registre algo que você não quer esquecer.")}
  function totals(){const t=calculateFinance(state);return{income:t.totalIncome,expenses:t.totalExpenses,balance:t.balance,reserve:t.reserves,investment:t.investmentsRecorded,budgets:t.budgets,monthIncome:t.monthIncome,monthExpenses:t.monthExpenses}}
  function renderFinance(){const t=totals();$("financeBalance").textContent=money(t.balance);$("financeReserve").textContent=money(t.reserve);$("financeInvestment").textContent=money(t.investment);$("transactionList").innerHTML=state.transactions.length?state.transactions.slice(0,30).map(x=>'<div class="list-row"><span class="stat-icon">'+(x.type==="income"?"↙":"↗")+'</span><div class="grow"><strong>'+safe(x.title)+'</strong><small>'+safe(new Date(x.createdAt).toLocaleDateString("pt-BR"))+'</small></div><strong style="color:'+(x.type==="income"?"var(--green)":"var(--red)")+'">'+(x.type==="income"?"+":"−")+money(x.amount)+'</strong><button class="delete-button" data-transaction-delete="'+x.id+'" aria-label="Excluir lançamento">×</button></div>').join(""):empty("Seus lançamentos aparecerão aqui.") ;$("assetList").innerHTML=state.assets.length?state.assets.map(a=>'<div class="list-row"><span class="stat-icon">'+(a.type==="reserve"?"◉":"↗")+'</span><div class="grow"><strong>'+safe(a.title)+'</strong><small>'+(a.type==="reserve"?"Reserva":"Investimento")+'</small></div><strong>'+money(a.amount)+'</strong><button class="delete-button" data-asset-delete="'+a.id+'" aria-label="Excluir objetivo">×</button></div>').join(""):empty("Adicione uma reserva ou registre um investimento que você já possui.");$("budgetList").innerHTML=t.budgets.length?t.budgets.map(b=>'<div class="list-row"><span class="stat-icon">◎</span><div class="grow"><strong>'+safe(b.category)+'</strong><small>'+money(b.spent)+' gastos de '+money(b.limit)+' · '+(b.percent===null?"Sem limite":b.percent+"% usado")+'</small></div><strong style="color:'+(b.remaining<0?"var(--red)":"var(--green)")+'">'+money(b.remaining)+'</strong><button class="delete-button" data-budget-delete="'+b.id+'" aria-label="Excluir orçamento">×</button></div>').join(""):empty("Defina um limite mensal para acompanhar os gastos por categoria.")}
  function renderOverview(){const today=state.tasks.filter(t=>t.date===dateKey());const activeReminders=state.reminders.filter(r=>!r.done);const shopping=state.shoppingLists.reduce((s,l)=>s+l.items.filter(i=>!i.done).length,0);const t=totals();$("overviewTasks").textContent=today.filter(x=>x.done).length+"/"+today.length;$("overviewTasksHint").textContent=today.length?(today.filter(x=>x.done).length===today.length?"Tudo concluído — boa!":"Um passo de cada vez"):"Nenhuma tarefa planejada";$("overviewReminders").textContent=activeReminders.length;$("overviewShopping").textContent=shopping;$("overviewBalance").textContent=money(t.balance);$("overviewIncome").textContent=money(t.monthIncome);$("overviewExpenses").textContent=money(t.monthExpenses);$("overviewInvestments").textContent=money(t.investment);const upcoming=[...state.tasks.filter(x=>!x.done).sort((a,b)=>(a.dueDate||a.date||"9999").localeCompare(b.dueDate||b.date||"9999"))].slice(0,4);$("overviewTaskList").innerHTML=upcoming.length?upcoming.map(x=>'<div class="list-row"><span class="check-bullet">○</span><div class="grow"><strong>'+safe(x.title)+'</strong><small>'+safe(x.category)+' · '+(x.date===dateKey()?"Hoje":safe(x.date))+'</small></div><button class="text-button" data-task-complete="'+x.id+'">Concluir</button></div>').join(""):empty("Nenhuma tarefa pendente. Se quiser, adicione uma pequena ação.");$("overviewReminderList").innerHTML=activeReminders.slice(0,4).length?activeReminders.slice(0,4).map(x=>'<div class="list-row"><span class="stat-icon">◷</span><div class="grow"><strong>'+safe(x.title)+'</strong><small>'+(x.when?safe(new Date(x.when).toLocaleString("pt-BR")):"Sem horário")+'</small></div></div>').join(""):empty("Sem lembretes pendentes.")}
  function renderAll(){renderOverview();renderTasks();renderShopping();renderReminders();renderFinance();$("notificationCount").textContent=state.reminders.filter(r=>!r.done).length}
  function quick(action){const map={task:["tasks","taskTitle"],shopping:["shopping","shoppingTitle"],reminder:["reminders","reminderTitle"],transaction:["finance","transactionTitle"]};if(action==="shopping"){switchView("shopping");$("shoppingTitle").focus();return}const target=map[action];if(!target)return;switchView(target[0]);const field=$(target[1]);if(field)field.focus()}
  document.querySelectorAll("[data-view]").forEach(el=>el.addEventListener("click",()=>switchView(el.dataset.view)));
  $("backHome").addEventListener("click",()=>switchView("overview"));
  $("notificationButton").addEventListener("click",()=>switchView("reminders"));
  document.querySelectorAll("[data-action]").forEach(el=>el.addEventListener("click",()=>{const action=el.dataset.action;if(action==="quick-add"){$("quickDialog").showModal();return}const map={"add-task":"task","add-shopping-list":"shopping","add-reminder":"reminder","add-transaction":"transaction"};quick(map[action])}));
  document.querySelectorAll("[data-dialog-action]").forEach(el=>el.addEventListener("click",()=>quick(el.dataset.dialogAction)));
  $("taskForm").addEventListener("submit",e=>{e.preventDefault();addTask($("taskTitle").value,$("taskCategory").value,$("taskPriority").value,$("taskRecurrence").value);e.target.reset();notify("Tarefa adicionada.")});
  $("seedRoutine").addEventListener("click",()=>{const basics=["Arrumar a cama","Beber água","Organizar um espaço por 5 minutos","Conferir as tarefas do dia"];const existing=state.tasks.filter(t=>t.date===dateKey()).map(t=>t.title.toLowerCase());const missing=basics.filter(x=>!existing.includes(x.toLowerCase()));missing.forEach(x=>addTask(x,"Casa","normal"));notify(missing.length?"Rotina básica adicionada. Ajuste ou exclua o que não fizer sentido.":"Sua rotina básica já está na lista.")});
  $("shoppingForm").addEventListener("submit",e=>{e.preventDefault();addShoppingList($("shoppingTitle").value);e.target.reset();notify("Lista criada.")});
  $("reminderForm").addEventListener("submit",e=>{e.preventDefault();addReminder($("reminderTitle").value,$("reminderDate").value);e.target.reset();notify("Lembrete salvo. Notificações do sistema ainda não estão conectadas.")});
  $("transactionForm").addEventListener("submit",e=>{e.preventDefault();const amount=Number($("transactionAmount").value);if(!Number.isFinite(amount)||amount<=0){notify("Informe um valor maior que zero.");return}state.transactions.unshift({id:uid(),title:$("transactionTitle").value.trim(),type:$("transactionType").value,amount,category:$("transactionCategory").value.trim()||"Sem categoria",date:dateKey(),createdAt:nowISO()});save();e.target.reset();renderAll();notify("Movimentação registrada localmente.")});
  $("assetForm").addEventListener("submit",e=>{e.preventDefault();const amount=Number($("assetAmount").value);if(!Number.isFinite(amount)||amount<0){notify("Informe um valor válido.");return}state.assets.unshift({id:uid(),title:$("assetTitle").value.trim(),type:$("assetType").value,amount,createdAt:nowISO()});save();e.target.reset();renderAll();notify("Reserva ou investimento salvo.")});
  $("budgetForm").addEventListener("submit",e=>{e.preventDefault();const category=$("budgetCategory").value.trim();const limit=Number($("budgetLimit").value);if(!category||!Number.isFinite(limit)||limit<=0){notify("Informe uma categoria e um limite maior que zero.");return}const existing=state.budgets.find(b=>b.category.toLowerCase()===category.toLowerCase());if(existing)existing.limit=limit;else state.budgets.unshift({id:uid(),category,limit,createdAt:nowISO()});save();e.target.reset();renderAll();notify("Orçamento mensal salvo.")});
  $("exportData").addEventListener("click",()=>{const payload=createExportPayload(state);const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="ruan-backup-"+dateKey()+".json";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);notify("Backup gerado. Guarde o arquivo em local privado.")});
  $("importData").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;try{const payload=JSON.parse(await file.text());const result=parseImportPayload(payload);if(!result.valid){notify("Backup recusado: "+result.errors.join(" "));return}if(!window.confirm("Importar este backup substituirá os dados atuais neste navegador. Exporte um backup atual antes de continuar. Deseja prosseguir?"))return;state=result.data;save();renderAll();notify("Backup importado. Confira os registros antes de continuar.")}catch{notify("Não foi possível ler esse arquivo JSON.")}finally{e.target.value=""}});
  document.addEventListener("change",e=>{const el=e.target;if(el.matches("[data-task-toggle]")){const t=state.tasks.find(x=>x.id===el.dataset.taskToggle);if(t){t.done=el.checked;if(el.checked&&t.recurrence){const nextDate=nextRecurrenceDate(t,new Date());if(nextDate&&!state.tasks.some(x=>x.title===t.title&&x.dueDate===nextDate&&x.recurrence===t.recurrence)){state.tasks.unshift({id:uid(),title:t.title,category:t.category,priority:t.priority,recurrence:t.recurrence,dueDate:nextDate,date:nextDate,done:false,createdAt:nowISO()})}}}save();renderAll()}else if(el.matches("[data-reminder-toggle]")){const r=state.reminders.find(x=>x.id===el.dataset.reminderToggle);if(r)r.done=el.checked;save();renderAll()}else if(el.matches("[data-item-toggle]")){const l=state.shoppingLists.find(x=>x.id===el.dataset.itemToggle);const i=l?.items.find(x=>x.id===el.dataset.itemId);if(i)i.done=el.checked;save();renderAll()}});
  document.addEventListener("submit",e=>{const form=e.target;if(!form.matches("[data-item-form]"))return;e.preventDefault();const input=form.elements.item;const l=state.shoppingLists.find(x=>x.id===form.dataset.itemForm);if(l&&input.value.trim())l.items.push({id:uid(),title:input.value.trim(),done:false});save();renderAll()});
  document.addEventListener("click",e=>{const el=e.target.closest("button");if(!el)return;const d=el.dataset;if(d.taskDelete){state.tasks=state.tasks.filter(x=>x.id!==d.taskDelete);save();renderAll()}if(d.taskComplete){const t=state.tasks.find(x=>x.id===d.taskComplete);if(t)t.done=true;save();renderAll()}if(d.listDelete){state.shoppingLists=state.shoppingLists.filter(x=>x.id!==d.listDelete);save();renderAll()}if(d.itemDelete){const l=state.shoppingLists.find(x=>x.id===d.itemDelete);if(l)l.items=l.items.filter(x=>x.id!==d.itemId);save();renderAll()}if(d.reminderDelete){state.reminders=state.reminders.filter(x=>x.id!==d.reminderDelete);save();renderAll()}if(d.transactionDelete){state.transactions=state.transactions.filter(x=>x.id!==d.transactionDelete);save();renderAll()}if(d.assetDelete){state.assets=state.assets.filter(x=>x.id!==d.assetDelete);save();renderAll()}if(d.budgetDelete){state.budgets=state.budgets.filter(x=>x.id!==d.budgetDelete);save();renderAll()}});
  $("todayLabel").textContent=new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"numeric",month:"long"});
  const hour=new Date().getHours();$("greeting").textContent=hour<12?"BOM DIA":hour<18?"BOA TARDE":"BOA NOITE";
  $("welcomeTitle").textContent=hour<12?"Vamos organizar seu dia.":hour<18?"Vamos por partes, sem pressa.":"Vamos deixar o amanhã mais leve.";
  renderAll();
})();